package com.infinitylibrary.community;

import com.infinitylibrary.InfinityLibraryPlugin;
import com.infinitylibrary.gui.LibraryMenu;
import com.infinitylibrary.model.*;
import com.infinitylibrary.storage.BookStorageManager.StoredBook;
import net.kyori.adventure.text.Component;
import org.bukkit.*;
import org.bukkit.block.Block;
import org.bukkit.entity.Player;
import org.bukkit.configuration.file.YamlConfiguration;
import java.nio.file.Path;
import java.util.*;

public final class NavigationManager {
    public record Bookmark(String world,Vector3i point){}
    private static final class Route {final Player player;final String label;final World world;final List<Vector3i> goals;final long expires;UUID libraryId;int next,searchTicks;WalkPathfinder search;List<Vector3i> path=List.of();Route(Player p,String label,World world,List<Vector3i> goals){player=p;this.label=label;this.world=world;this.goals=List.copyOf(goals);expires=System.nanoTime()+java.util.concurrent.TimeUnit.MINUTES.toNanos(3);}}
    private final InfinityLibraryPlugin plugin;private final Path file;private final Map<UUID,Map<String,Bookmark>> bookmarks=new HashMap<>();private final Map<UUID,Route> routes=new LinkedHashMap<>();private int ticks,task,cursor;private final Map<UUID,Long> requests=new HashMap<>();
    private static final Set<Material> HAZARDS=EnumSet.of(Material.LAVA,Material.FIRE,Material.SOUL_FIRE,Material.CACTUS,Material.MAGMA_BLOCK,Material.CAMPFIRE,Material.SOUL_CAMPFIRE,Material.POWDER_SNOW,Material.SWEET_BERRY_BUSH);
    public NavigationManager(InfinityLibraryPlugin p){plugin=p;file=p.getDataFolder().toPath().resolve("bookmarks.yml");load();task=Bukkit.getScheduler().scheduleSyncRepeatingTask(plugin,this::tick,1,1);}
    public void load(){
        var y=AtomicYaml.read(file);Map<UUID,Map<String,Bookmark>> loaded=new HashMap<>();var root=y.getConfigurationSection("players");
        if(root!=null)for(String player:root.getKeys(false)){Map<String,Bookmark> entries=new TreeMap<>();var s=root.getConfigurationSection(player);for(String name:s.getKeys(false)){var b=s.getConfigurationSection(name);entries.put(name,new Bookmark(b.getString("world"),Vector3i.read(b.getConfigurationSection("point"))));}loaded.put(UUID.fromString(player),entries);}
        bookmarks.clear();bookmarks.putAll(loaded);loadFavorites();
    }
    public void save(){YamlConfiguration y=new YamlConfiguration();bookmarks.forEach((player,entries)->entries.forEach((name,b)->{var s=y.createSection("players."+player+"."+name);s.set("world",b.world());b.point().write(s.createSection("point"));}));AtomicYaml.write(file,y);}
    public Map<String,Bookmark> bookmarks(Player p){return Map.copyOf(bookmarks.getOrDefault(p.getUniqueId(),Map.of()));}
    public void bookmark(Player p,String name){library(p);if(!name.matches("[a-z0-9_-]{1,32}"))throw new IllegalArgumentException("Bookmark names need 1–32 lowercase letters/digits/_/-.");var entries=bookmarks.computeIfAbsent(p.getUniqueId(),id->new TreeMap<>());if(!entries.containsKey(name)&&entries.size()>=20)throw new IllegalArgumentException("Maximum 20 personal bookmarks.");var old=entries.put(name,new Bookmark(p.getWorld().getName(),Vector3i.from(p.getLocation())));try{save();}catch(RuntimeException ex){if(old==null)entries.remove(name);else entries.put(name,old);throw ex;}}
    public void removeBookmark(Player p,String name){var entries=bookmarks.getOrDefault(p.getUniqueId(),new TreeMap<>());Bookmark old=entries.remove(name);if(old==null)throw new IllegalArgumentException("Bookmark not found.");try{save();}catch(RuntimeException ex){entries.put(name,old);throw ex;}}
    private record Favorite(UUID library,UUID room){}
    private final Map<UUID,Set<Favorite>> favorites=new HashMap<>();
    private Path favoritesFile(){return plugin.getDataFolder().toPath().resolve("room-favorites.yml");}
    private void loadFavorites(){var y=AtomicYaml.read(favoritesFile());Map<UUID,Set<Favorite>> next=new HashMap<>();var root=y.getConfigurationSection("players");if(root!=null)for(String id:root.getKeys(false)){Set<Favorite> list=new HashSet<>();for(String row:root.getStringList(id)){String[] parts=row.split("/",2);list.add(new Favorite(UUID.fromString(parts[0]),UUID.fromString(parts[1])));}next.put(UUID.fromString(id),list);}favorites.clear();favorites.putAll(next);}
    private void saveFavorites(){var y=new YamlConfiguration();favorites.forEach((id,list)->y.set("players."+id,list.stream().map(f->f.library()+"/"+f.room()).sorted().toList()));AtomicYaml.write(favoritesFile(),y);}
    public boolean favorite(Player p,UUID room){return favorites.getOrDefault(p.getUniqueId(),Set.of()).contains(new Favorite(plugin.getGenerationEngine().libraryId(),room));}
    public void toggleFavorite(Player p,UUID room){if(plugin.getGenerationEngine().navigationRooms().stream().noneMatch(n->n.id().equals(room)))throw new IllegalArgumentException("Generated room not found.");Set<Favorite> previous=new HashSet<>(favorites.getOrDefault(p.getUniqueId(),Set.of()));Set<Favorite> next=new HashSet<>(previous);Favorite f=new Favorite(plugin.getGenerationEngine().libraryId(),room);if(!next.remove(f)){if(next.size()>=100)throw new IllegalArgumentException("Maximum 100 favorite rooms.");next.add(f);}favorites.put(p.getUniqueId(),next);try{saveFavorites();}catch(RuntimeException ex){favorites.put(p.getUniqueId(),previous);throw ex;}}
    public void currentRoom(Player p){library(p);var room=new RoomGraph(plugin.getGenerationEngine().navigationRooms()).containing(Vector3i.from(p.getLocation())).orElseThrow(()->new IllegalArgumentException("Stand inside a completed room."));p.sendMessage("Room "+room.id()+" • "+room.template()+" • "+room.type());}

    private void library(Player p){if(!p.getWorld().getName().equals(plugin.getGenerationEngine().worldName()))throw new IllegalArgumentException("Enter the library world before starting a route.");}
    public WalkPathfinder.Terrain terrain(World world){return new WalkPathfinder.Terrain(){
        private boolean loaded(Vector3i p){return p.y()>=world.getMinHeight()&&p.y()<world.getMaxHeight()&&world.isChunkLoaded(p.x()>>4,p.z()>>4);}
        private boolean hazard(Material m){return HAZARDS.contains(m);}
        public boolean clear(Vector3i p){if(!loaded(p))return false;Block b=world.getBlockAt(p.x(),p.y(),p.z());return b.isPassable()&&!hazard(b.getType())&&!b.isLiquid();}
        public boolean climb(Vector3i p){if(!loaded(p))return false;Material m=world.getBlockAt(p.x(),p.y(),p.z()).getType();return m==Material.LADDER||m==Material.VINE||m==Material.SCAFFOLDING||m==Material.TWISTING_VINES||m==Material.WEEPING_VINES;}
        public boolean stand(Vector3i p){if(p.y()<=world.getMinHeight()||p.y()+1>=world.getMaxHeight())return false;if(!clear(p)||!clear(p.add(new Vector3i(0,1,0))))return false;if(climb(p))return true;Block floor=world.getBlockAt(p.x(),p.y()-1,p.z());return floor.getType().isSolid()&&!floor.isPassable()&&!hazard(floor.getType())&&floor.getCollisionShape().getBoundingBoxes().stream().noneMatch(box->box.getMaxY()>1.001);}
    };}
    private Vector3i nearby(World world,Vector3i point,int radius){var terrain=terrain(world);if(terrain.stand(point))return point;for(int r=1;r<=radius;r++)for(int dy=-Math.min(r,2);dy<=Math.min(r,2);dy++)for(int dx=-r;dx<=r;dx++)for(int dz=-r;dz<=r;dz++)if(Math.max(Math.max(Math.abs(dx),Math.abs(dz)),Math.abs(dy))==r){var p=point.add(new Vector3i(dx,dy,dz));if(terrain.stand(p))return p;}throw new IllegalArgumentException("No loaded, safe walking position near this destination. Vertical routes need stairs or ladders.");}
    private void cooldown(Player p){if(System.nanoTime()-requests.getOrDefault(p.getUniqueId(),0L)<java.util.concurrent.TimeUnit.SECONDS.toNanos(1))throw new IllegalArgumentException("Wait a moment before starting another route.");}
    public void start(Player p,String label,Location target){library(p);cooldown(p);if(target==null||target.getWorld()!=p.getWorld())throw new IllegalArgumentException("Destination is not in this library world.");if(!routes.containsKey(p.getUniqueId())&&routes.size()>=Math.max(1,Math.min(64,plugin.getConfig().getInt("navigation.max-active-routes",32))))throw new IllegalArgumentException("Navigation is busy. Try again shortly.");var rooms=plugin.getGenerationEngine().navigationRooms();if(rooms.size()>Math.max(100,plugin.getConfig().getInt("navigation.max-graph-rooms",5000)))throw new IllegalArgumentException("Library exceeds the configured navigation graph limit.");RoomGraph graph=new RoomGraph(rooms);var source=graph.containing(Vector3i.from(p.getLocation())).orElseThrow(()->new IllegalArgumentException("Stand inside a completed library room first."));Vector3i dest=nearby(p.getWorld(),Vector3i.from(target),4);var end=graph.containing(dest).orElseThrow(()->new IllegalArgumentException("Destination is outside completed library rooms."));List<Vector3i> goals=new ArrayList<>(graph.route(source.id(),end.id()).orElseThrow(()->new IllegalArgumentException("No connected-room route to that destination.")));goals.add(dest);Route route=new Route(p,label,p.getWorld(),goals);route.libraryId=plugin.getGenerationEngine().libraryId();requests.put(p.getUniqueId(),System.nanoTime());plugin.getPreviewManager().stop(p);routes.put(p.getUniqueId(),route);p.closeInventory();p.sendMessage(Component.text("Following particles to "+label+". /il navigate stop to cancel."));}
    public void destination(Player p,String type){library(p);cooldown(p);if(type.equalsIgnoreCase("entrance")){start(p,"entrance",plugin.getGenerationEngine().homeLocation());return;}RoomType role=type.equalsIgnoreCase("reading")?RoomType.READ:type.equalsIgnoreCase("books")?RoomType.BOOK:null;if(role==null)throw new IllegalArgumentException("Use entrance, reading, books, room, book, bookmark or stop.");RoomGraph graph=new RoomGraph(plugin.getGenerationEngine().navigationRooms());var from=graph.containing(Vector3i.from(p.getLocation())).orElseThrow(()->new IllegalArgumentException("Stand inside a completed room."));var room=graph.closestReachable(from.id(),role).orElseThrow(()->new IllegalArgumentException("No connected "+type+" room has been generated yet."));start(p,type+" room",RoomGraph.center(room).toLocation(p.getWorld()));}
    public void room(Player p,UUID id){var room=plugin.getGenerationEngine().navigationRooms().stream().filter(n->n.id().equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("Room not found."));start(p,room.template(),RoomGraph.center(room).toLocation(plugin.getGenerationEngine().ensureWorld()));}
    public void book(Player p,UUID id){StoredBook b=plugin.getBookStorageManager().allBooks().stream().filter(x->x.id().equals(id)&&(x.isPublic()||x.ownerUuid().equals(p.getUniqueId().toString()))).findFirst().orElseThrow(()->new IllegalArgumentException("Book not found or private."));Location location=plugin.getBookStorageManager().bookLocation(b);if(location==null)throw new IllegalArgumentException("This book is in the collection but has no placed bookshelf yet. You can still read it in the library reader.");start(p,"bookshelf: "+b.title(),location);}
    public void bookmarkRoute(Player p,String name){Bookmark b=bookmarks(p).get(name);if(b==null)throw new IllegalArgumentException("Bookmark not found.");World w=Bukkit.getWorld(b.world());if(w==null)throw new IllegalArgumentException("Bookmark world is not loaded.");start(p,name,b.point().toLocation(w));}
    public void stop(Player p){routes.remove(p.getUniqueId());p.sendActionBar(Component.text("Navigation stopped."));}
    public int activeCount(){return routes.size();}
    public void clearRoutes(){routes.clear();requests.clear();}
    public void shutdown(){Bukkit.getScheduler().cancelTask(task);clearRoutes();}
    private void fail(Route r,String reason){routes.remove(r.player.getUniqueId());r.player.sendMessage(Component.text(reason));}
    private boolean nearAndClear(Route r,Vector3i from,Vector3i to){if(to.toLocation(r.world).add(.5,0,.5).distanceSquared(r.player.getLocation())>=2.5)return false;var t=terrain(r.world);if(!t.stand(from)){Vector3i above=from.add(new Vector3i(0,1,0));if(!t.stand(above))return false;from=above;}for(int i=0;i<=4;i++){double f=i/4.0;var p=new Vector3i((int)Math.round(from.x()+(to.x()-from.x())*f),(int)Math.round(from.y()+(to.y()-from.y())*f),(int)Math.round(from.z()+(to.z()-from.z())*f));if(!t.stand(p))return false;}return true;}
    private void tick(){ticks++;List<Route> work=new ArrayList<>(routes.values());if(work.isEmpty())return;int budget=Math.max(20,Math.min(4000,plugin.getConfig().getInt("navigation.nodes-per-tick",600)));int start=Math.floorMod(cursor,work.size());for(int i=0;i<work.size();i++){Route r=work.get((start+i)%work.size());Player p=r.player;if(!p.isOnline()||p.getWorld()!=r.world||!p.hasPermission("infinitylibrary.command")||System.nanoTime()>r.expires){routes.remove(p.getUniqueId());continue;}if(!Objects.equals(r.libraryId,plugin.getGenerationEngine().libraryId())){fail(r,"Library layout changed; choose a new navigation destination.");continue;}Vector3i at=Vector3i.from(p.getLocation());while(r.next<r.goals.size()&&nearAndClear(r,at,r.goals.get(r.next))){r.next++;r.path=List.of();r.search=null;}if(r.next>=r.goals.size()){fail(r,"You have arrived at "+r.label+".");continue;}
        if(r.search==null&&r.path.isEmpty()){try{Vector3i from=nearby(r.world,at,2),to=nearby(r.world,r.goals.get(r.next),3);r.search=new WalkPathfinder(terrain(r.world),from,to,Math.max(100,Math.min(50000,plugin.getConfig().getInt("navigation.max-search-nodes",10000))),Math.max(16,Math.min(256,plugin.getConfig().getInt("navigation.segment-range",96))));r.searchTicks=0;}catch(IllegalArgumentException ex){fail(r,ex.getMessage());continue;}}
        if(r.search!=null){if(budget>0){int used=r.search.advance(Math.min(150,budget));budget-=used;}if(r.search.status()==WalkPathfinder.Status.FAILED||++r.searchTicks>240){fail(r,"No safe walking path to "+r.label+". Check blocked doors, loaded chunks, stairs and ladders.");continue;}if(r.search.status()==WalkPathfinder.Status.FOUND){r.path=r.search.path();r.search=null;}}
        if(ticks%10==0&&!r.path.isEmpty()){int nearest=0;double best=Double.MAX_VALUE;for(int n=0;n<r.path.size();n++){double d=r.path.get(n).toLocation(r.world).add(.5,0,.5).distanceSquared(p.getLocation());if(d<best&&nearAndClear(r,at,r.path.get(n))){best=d;nearest=n;}}if(best>16){r.path=List.of();continue;}int shown=0;var terrain=terrain(r.world);boolean blocked=false;for(int n=nearest;n<r.path.size()&&shown<28;n++){Vector3i step=r.path.get(n);if(!terrain.stand(step)){blocked=true;break;}Location point=step.toLocation(r.world).add(.5,.18,.5);if(point.distanceSquared(p.getLocation())>256)break;p.spawnParticle(Particle.END_ROD,point,1,0,0,0,0);shown++;}if(blocked){r.path=List.of();continue;}p.sendActionBar(Component.text("✦ "+r.label+" · "+(r.goals.size()-r.next)+" waypoint(s)"));}
    }cursor=(start+1)%work.size();}
    public void browser(Player p){LibraryMenu m=new LibraryMenu(p,LibraryMenu.Screen.NAVIGATION,54,"Library • Particle navigation");var w=plugin.getBookWritingManager();w.icon(m.getInventory(),10,Material.COMPASS,"Trail to entrance");w.icon(m.getInventory(),12,Material.LECTERN,"Nearest connected reading room");w.icon(m.getInventory(),14,Material.BOOKSHELF,"Nearest connected book room");w.icon(m.getInventory(),16,Material.BARRIER,"Stop current trail");int slot=18;for(String name:new TreeSet<>(bookmarks(p).keySet())){if(slot>=45)break;m.entry(slot,name);w.icon(m.getInventory(),slot++,Material.ENDER_EYE,name,"§eLeft: follow trail · Right: remove bookmark");}w.icon(m.getInventory(),45,Material.MAP,"Browse generated rooms");w.icon(m.getInventory(),51,Material.BOOK,"Books and bookshelf routes");w.icon(m.getInventory(),47,Material.NAME_TAG,"Save current location");w.icon(m.getInventory(),49,Material.CHEST,"Main menu");p.openInventory(m.getInventory());}
    public void rooms(Player p,int page){var list=plugin.getGenerationEngine().navigationRooms().stream().sorted(Comparator.<RoomGraph.RoomNode>comparingInt(n->favorite(p,n.id())?0:1).thenComparing(RoomGraph.RoomNode::template).thenComparing(n->n.id().toString())).toList();page=Math.max(0,Math.min(page,Math.max(0,(list.size()-1)/45)));LibraryMenu m=new LibraryMenu(p,LibraryMenu.Screen.NAV_ROOMS,54,"Library • Generated rooms");m.entry(53,Integer.toString(page));var w=plugin.getBookWritingManager();for(int i=0;i<45&&page*45+i<list.size();i++){var n=list.get(page*45+i);m.entry(i,n.id().toString());w.icon(m.getInventory(),i,Material.BRICKS,(favorite(p,n.id())?"★ ":"")+n.template(),"§7"+n.type()+" · "+n.box().origin(),"§7Room "+n.id().toString().substring(0,8),"§eLeft: trail · Right: favorite");}w.icon(m.getInventory(),45,Material.ARROW,"Previous");w.icon(m.getInventory(),49,Material.COMPASS,"Navigation menu");w.icon(m.getInventory(),51,Material.ARROW,"Next");p.openInventory(m.getInventory());}
    public void handle(Player p,LibraryMenu m,int slot,boolean right){if(m.screen()==LibraryMenu.Screen.NAV_ROOMS){int page=Integer.parseInt(m.entry(53));if(slot<45&&m.entry(slot)!=null){if(right){toggleFavorite(p,UUID.fromString(m.entry(slot)));rooms(p,page);}else room(p,UUID.fromString(m.entry(slot)));}else if(slot==45)rooms(p,page-1);else if(slot==51)rooms(p,page+1);else if(slot==49)browser(p);return;}if(slot==45){rooms(p,0);return;}if(slot==51){plugin.getReadingManager().browser(p,0,false);return;}if(slot==10)destination(p,"entrance");else if(slot==12)destination(p,"reading");else if(slot==14)destination(p,"books");else if(slot==16){stop(p);browser(p);}else if(slot==49)plugin.getGuiManager().openMainMenu(p);else if(slot==47)plugin.getManagedDialogs().form(p,"Save bookmark",List.of(io.papermc.paper.registry.data.dialog.input.DialogInput.text("name",Component.text("Name (lowercase letters/digits/_/-)")).maxLength(32).build()),r->{bookmark(p,r.getText("name"));browser(p);},()->browser(p));else if(m.entry(slot)!=null){if(right){removeBookmark(p,m.entry(slot));browser(p);}else bookmarkRoute(p,m.entry(slot));}}
}
